body:
I made the nodejs setup work too as a workaround for now, so I used @goatchurchprime`s suggestion of adding this to the client code in Godot:

```gdscript
func _send_msg(type: int, id: int, data: String = "") -> Error:
	return ws.send_text(JSON.stringify({
		"type": str(type),
		"id": str(id),
		"data": data,
	}))
```

In server.js I changed the parseMsg function as well as the ProtoMessage to accomodate to the changes above:
```gdscript
function ProtoMessage(type, id, data) {
	return JSON.stringify({
		'type': type.toString(),
		'id': id.toString(),
		'data': data || '',
	});
}
```

```javascript
function parseMsg(peer, msg) {
    let json = null;
    try {
        json = JSON.parse(msg);
    } catch (e) {
        throw new ProtoError(4000, STR_INVALID_FORMAT);
    }

    const type = parseInt(json['type'], 10);
    const id = parseInt(json['id'], 10);
    const data = typeof json['data'] === 'string' ? json['data'] : '';

    if (isNaN(type) || isNaN(id)) {
        throw new ProtoError(4000, STR_INVALID_FORMAT);
    }

    // Lobby joining.
    if (type === CMD.JOIN) {
        joinLobby(peer, data, id === 0);
        return;
    }

    if (!peer.lobby) {
        throw new ProtoError(4000, STR_NEED_LOBBY);
    }
    const lobby = lobbies.get(peer.lobby);
    if (!lobby) {
        throw new ProtoError(4000, STR_SERVER_ERROR);
    }

    // Lobby sealing.
    if (type === CMD.SEAL) {
        lobby.seal(peer);
        return;
    }

    // Message relaying format:
    // { "type": CMD.[OFFER|ANSWER|CANDIDATE], "id": DEST_ID, "data": PAYLOAD }
    if (type === CMD.OFFER || type === CMD.ANSWER || type === CMD.CANDIDATE) {
        let destId = id;
        if (id === 1) {
            destId = lobby.host;
        }
        const dest = lobby.peers.find((e) => e.id === destId);
        if (!dest) {
            throw new ProtoError(4000, STR_INVALID_DEST);
        }
        dest.ws.send(ProtoMessage(type, lobby.getPeerId(peer), data));
        return;
    }
    throw new ProtoError(4000, STR_INVALID_CMD);
}
```
